Translate("deDE", "stranglethorn-vale", {
	title = "Schlingendorntal",
	aliases = { "Schlingendorn", "das Tal" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Schlingendorntal ist der große Dschungel des Südens. Es reicht von den finsteren Grenzen des {link:duskwood}Dämmerwalds{/link} bis zu einem felsigen Kap, an dem das Land im Meer endet. Seine Bäume sind alt und hoch, seine Flüsse wimmeln von Krokilisken, und Tiger, Panther, Raptoren und Affen jagen unter seinem grünen Dach. Überall haben die Ranken die Steine eines gefallenen Trollreiches verschlungen. Keine Krone herrscht hier. Goblins halten den Hafen von {link:booty-bay}Booty Bay{/link}, die {link:horde}Horde{/link} unterhält ein Lager an der Westküste, Jäger und Deserteure aus dem Norden schlagen ihre Zelte in den Hügeln auf, und die Trollstämme führen ihre alten Kriege in den Ruinen ihrer Väter.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Einst war dies das Herz der Gurubashi, der Dschungeltrolle des Südens. In den Zeitaltern vor der {link:great-sundering}Großen Teilung{/link} erstreckte sich ihr Reich über diese Lande und weit darüber hinaus. Als die Welt zerbrach, verlor das Reich viel von seinem Land an das Meer, und in ihrer Not wandten sich seine Bewohner finsterer Anbetung zu. Die Priester der Atal'ai riefen in ihrer {link:capital-city}Hauptstadt{/link} {link:zul-gurub}Zul'Gurub{/link} {link:hakkar}Hakkar{/link} herbei, den Blutgott. Der Gott nährte sich von seinen Anbetern, und schließlich erhoben sich die Stämme gegen ihn und seine Priester. Sie verstießen Hakkar und trieben die Atal'ai in die Sümpfe im Norden. Das Reich der Gurubashi erholte sich nie. Seine Stämme wandten sich gegeneinander, und die Städte, die sie erbaut hatten, blieben dem Dschungel überlassen.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Das Schlingendorntal hat keinen Herrn, und darum hat es viele. Die Goblins des {link:steamwheedle-cartel}Steamwheedle-Kartells{/link} beherrschen {link:booty-bay}Booty Bay{/link} an der Südspitze, wo jede Flagge willkommen ist, solange sie zahlt. Piraten zweier verfeindeter Flotten, der {red:blackwater-raiders}Schwarzmeerräuber{/red} und der {red:bloodsail-buccaneers}Blutsegelbukaniere{/red}, kämpfen um die Gewässer des Kaps. Die {link:venture-company}Venture Company{/link} plündert die nördlichen Hügel nach Holz und Kristall. Im Norden führt eine Schar Soldaten aus {link:stormwind-city}Stormwind{/link} einen verzweifelten Krieg gegen ihren eigenen früheren Oberst. An der Westküste hat die {link:horde}Horde{/link} {link:grom-gol-base-camp}Grom'gol{/link} errichtet, und ihre Gesandten der {link:darkspear-trolls}Darkspear{/link} sind heimgekehrt, um einen verlorenen Sohn ihres Stammes zu suchen. Der berühmte Jäger {link:hemet-nesingwary}Hemet Nesingwary{/link} ist gekommen, um die großen Bestien des Dschungels zu jagen. Und hinter alledem harren die {link:trolls}Trolle{/link} aus: die Bloodscalp, die Skullsplitter und die Anhänger des ausgestoßenen {link:zanzil-the-outcast}Zanzil{/link}, jeder noch immer im Krieg mit den anderen.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Die Goblins von {link:booty-bay}Booty Bay{/link}.{/b} Händler, Makler und Schläger des {link:steamwheedle-port}Steamwheedle{/link}-Kartells, und die Piraten der Schwarzmeerräuber, die in ihren Tavernen trinken.
• {b}Die Blutsegelbukaniere.{/b} Rivalisierende Piraten, die an den wilden Ufern gelandet sind und Pläne gegen den Hafen schmieden.
• {b}Die Stämme der Gurubashi.{/b} Die Bloodscalptrolle in den Ruinen im Nordwesten, die Skullsplittertrolle in den Ruinen der Mitte und die Anhänger Zanzils auf dem Kap. Hinter den Mauern von {link:zul-gurub}Zul'Gurub{/link} regen sich noch ältere Mächte.
• {b}Die Rebellen und die Deserteure.{/b} Die Rebellen von {link:lieutenant-doren}Leutnant Doren{/link} im Norden und die Männer von {link:colonel-kurzen}Oberst Kurzen{/link} im Truppenlager östlich davon.
• {b}Die {link:horde}Horde{/link} in {link:grom-gol-base-camp}Grom'gol{/link}.{/b} {link:orcs}Orcs{/link} und {link:darkspear-trolls}Trolle der Darkspear{/link}, die den Nachschubweg nach {link:stonard}Stonard{/link} und die Zeppeline in den Norden bewachen.
• {b}Die Jäger.{/b} {link:hemet-nesingwary}Hemet Nesingwary{/link} und seine Gefährten, die am nördlichen Fluss lagern.
• {b}Die {link:ogres}Oger{/link}.{/b} Der Klan der {link:mosh-ogg-ogre-mound}Mosh'Ogg{/link} hält einen Hügel in den östlichen Bergen und die {link:mizjah-ruins}Ruinen von Mizjah{/link}.
• {b}Die {link:naga}Naga{/link}, die {link:murlocs}Murlocs{/link} und die Riesen des Meeres.{/b} Sie suchen die Küsten, die versunkenen Ruinen und die Riffe heim.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Das Reich.{/b} Lange Zeitalter herrschten die Gurubashi von {link:zul-gurub}Zul'Gurub{/link} aus über diese Dschungel. Ihre Steinstädte erhoben sich entlang der Flüsse und Küsten.
• {b}Der Seelenschinder.{/b} {link:hakkar}Hakkar{/link} wurde von den Atal'ai in die Welt gerufen. Seine Anbetung stürzte das Reich in den Bürgerkrieg, und seine Niederlage ließ es zerschlagen zurück.
• {b}Die Zerstreuung.{/b} Die Stämme der Gurubashi kämpften untereinander um das, was übrig blieb. Der {link:darkspear-trolls}Stamm der Darkspear{/link} wurde aus dem Dschungel vertrieben und zog auf die Inseln der südlichen Meere.
• {b}Die Goblins.{/b} Die Goblins vertrieben die {link:trolls}Trolle{/link} aus einem Hafen an der Südspitze des Dschungels und erbauten darauf {link:booty-bay}Booty Bay{/link}. Keine Chronik des Dschungels verzeichnet das Jahr.
• {b}Die Gegenwart.{/b} Nordländer sind in wachsender Zahl gekommen: Soldaten, Jäger, Bergleute und die {link:horde}Horde{/link}. Keiner von ihnen hat das Tal gezähmt.]=],
		},
		{
			title = "Überlieferungen des Dschungels",
			text = [=[• Jedes Volk Azeroths, so heißt es, beansprucht das Wasser der heiligen Quelle auf den westlichen Klippen als eine Gabe, die allein für die eigene Art geheiligt wurde.
• Die Soldaten des Rebellenlagers erzählen einander, dass die Goblins von {link:booty-bay}Booty Bay{/link} betrunkene Seeleute an Bord von Sklavenschiffen schleppen und sie an Orte bringen, die niemand nennt.
• Eine Krankheit namens Schlingendornfieber streckt Seeleute auf dem Kap nieder. Das einzige Heilmittel, sagen die Hexendoktoren, ist das Herz eines weißen Affen, den niemand finden kann.
• {link:hemet-nesingwary}Hemet Nesingwary{/link} hat ein Buch über seine Jagden im Dschungel geschrieben. Seine Seiten wurden einst vom Wind davongetragen, und noch heute soll der Dschungel einige von ihnen verbergen.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine Chronik verzeichnet die Jahre, in denen das Reich der Gurubashi aufstieg, fiel oder sich zerstreute, noch das Jahr, in dem die Goblins {link:booty-bay}Booty Bay{/link} einnahmen.]=],
		},
	},
})

Translate("deDE", "booty-bay", {
	title = "Booty Bay",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Booty Bay ist der Goblinhafen an der Südspitze des Schlingendorntals. Der Weg vom Dschungel hinein führt durch einen Tunnel in den Klippen, und die Stadt selbst klammert sich an die Wände einer tiefen Bucht, Ring um Ring aus Holzhäusern und Stegen rund um einen belebten Hafen. {link:baron-revilgaz}Baron Revilgaz{/link} herrscht vom obersten Stockwerk der Taverne aus. Die Schläger des {link:steamwheedle-cartel}Steamwheedle-Kartells{/link} wahren den Frieden zwischen {link:alliance}Allianz{/link} und {link:horde}Horde{/link}, und Piraten der {red:blackwater-raiders}Schwarzmeerräuber{/red} füllen zwischen ihren Fahrten die Gasthäuser. Von seinen Docks segeln Schiffe über das Meer nach {link:ratchet}Ratchet{/link}. Alles kann man hier kaufen, und das meiste kann man verkaufen.]=],
		},
	},
})

Translate("deDE", "gurubashi-arena", {
	title = "Die Arena der Gurubashi",
	aliases = { "die Arena" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Arena der Gurubashi ist ein großer Steinring im Herzen des Dschungels, von den Trollen in den Tagen ihres Reiches errichtet. Ihre Ränge stehen noch, rissig und überwuchert, rund um einen sandigen Boden. Die {link:trolls}Trolle{/link} haben sie inzwischen verlassen. Von Zeit zu Zeit stellt ein Pirat namens {link:short-john-mithril}Short John Mithril{/link} eine Schatztruhe auf den Boden und lässt die kühnsten Kämpfer des Dschungels einander darum töten. Wer immer wieder siegt, sagt er, darf sich Meister der Arena nennen.]=],
		},
	},
})

Translate("deDE", "zul-gurub", {
	title = "Zul'Gurub",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Zul'Gurub war die große Stadt der Gurubashitrolle, und von hier aus beherrschte ihr Reich einst den Süden. Hier riefen die Priester der Atal'ai {link:hakkar}Hakkar{/link} den Seelenschinder in die Welt, und hier erhoben sich die Stämme, um ihn zu stürzen. Die Stadt liegt im Nordosten des Dschungels, hinter Mauern, die die Ranken nicht gebrochen haben. Ihre Tore sind verschlossen. Krieger der Gurubashi und Priester der Hakkari halten noch immer vor ihnen Wache, und eine Hohepriesterin wandelt unter ihnen. Wer in der Nähe lebt, fragt nicht, was drinnen geschieht.]=],
		},
		{
			title = "In diesen Tagen",
			text = [=[Die {link:darkspear-trolls}Darkspear{/link} haben die Stadt nicht vergessen. Nach Zul'Gurub gab der Stamm einst den jüngsten Sohn des Häuptlings, {link:yenniku}Yenniku{/link}, wie es der Brauch verlangte. Nun spricht {link:vol-jin}Vol'jin{/link} von kommenden Schlachten gegen ihre {link:trolls}Trolle{/link}. In letzter Zeit hat man einen Troll des fernen Stammes der Zandalar gesehen, der ihre Mauern beobachtet.]=],
		},
	},
})

Translate("deDE", "nesingwary-s-expedition", {
	title = "Nesingwarys Expedition",
	aliases = { "Nesingwarys Lager" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Nesingwarys Expedition ist ein Jagdlager im Norden des Dschungels, flussaufwärts von den Anlagen der {link:venture-company}Venture Company{/link} am Nazferitisee. Seine Zelte stehen rund um ein Feuer, und Jagdtrophäen liegen offen zur Schau. Hier haben sich der {link:dwarves}Zwerg{/link} {link:hemet-nesingwary}Hemet Nesingwary{/link} und seine Gefährten versammelt, um die großen Bestien des Schlingendorntals zu jagen: Tiger, Panther und Raptoren, und vor allem einen weißen Tiger. Die Jäger heißen Fremde willkommen, die gerade schießen können. Mit allen anderen haben sie wenig Geduld.]=],
		},
	},
})

Translate("deDE", "rebel-camp", {
	title = "Rebellenlager",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Rebellenlager liegt im äußersten Norden des Dschungels, nahe der Straße, die aus dem {link:duskwood}Dämmerwald{/link} herabführt. Es ist eine kleine Palisade aus Zelten und Kisten, gehalten von Soldaten aus {link:stormwind-city}Stormwind{/link}, die einst {link:colonel-kurzen}Oberst Kurzen{/link} folgten und sich gegen ihn gewandt haben. {link:lieutenant-doren}Leutnant Doren{/link} befehligt sie. Sie sind wenige, und die Männer des Obersts sind ihnen um ein Vielfaches überlegen. Die Goblins von {link:booty-bay}Booty Bay{/link} schicken ihnen Vorräte, darunter Landminen, um die Zugänge des Lagers zu sichern. Jeder Soldat hier weiß, dass ein einziger Verräter ihnen allen das Ende bringen könnte.]=],
		},
	},
})

Translate("deDE", "kurzen-s-compound", {
	title = "Kurzens Truppenlager",
	aliases = { "Kurzens Lager", "Das Vorratslager" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Kurzens Truppenlager liegt östlich des Rebellenlagers in den nördlichen Hügeln. Es wurde von Soldaten erbaut, und das sieht man. Seine Zäune, Türme und Vorratsstapel sind sorgfältig angelegt, und sein einziges zweistöckiges Haus beherbergte einst die Amtsstube des Vorratsverwalters des Obersts. Dschungelkämpfer, Medizinmänner und Kommandosoldaten halten es jetzt. An seiner Rückseite öffnet sich eine Höhle in den Hügel. Die Männer des Obersts nennen sie das Vorratslager, und tief darin führt {link:colonel-kurzen}Oberst Kurzen{/link} selbst das Kommando.]=],
		},
	},
})

Translate("deDE", "grom-gol-base-camp", {
	title = "Das Basislager von Grom'gol",
	aliases = { "Grom'gol" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Basislager von Grom'gol ist der Außenposten des Kriegshäuptlings an der Westküste des Schlingendorntals. Die {link:horde}Horde{/link} kam nicht in den Dschungel, um gegen seine Stämme Krieg zu führen. Sie kam, um eine Nachschublinie nach {link:stonard}Stonard{/link} offen zu halten, ihrer Festung in den Sümpfen im Nordosten. Doch Raptoren jagen auf den Straßen, {link:ogres}Oger{/link} überfallen die Karawanen, und das Lager musste um jeden Tag kämpfen, den es besteht. Von seinen Türmen steigen Zeppeline nach {link:orgrimmar}Orgrimmar{/link} und {link:undercity}Undercity{/link} auf. Auch Gesandte der {link:darkspear-trolls}Darkspear{/link} wirken hier, in einer eigenen Mission.]=],
		},
	},
})

Translate("deDE", "ruins-of-zul-kunda", {
	title = "Ruinen von Zul'Kunda",
	aliases = { "Zul'Kunda" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Ruinen von Zul'Kunda stehen an der Nordwestküste des Dschungels, wo einst eine Trollstadt auf das Meer hinausblickte. Der Stamm der Bloodscalp hält sie jetzt. Ihr Häuptling {link:gan-zulah}Gan'zulah{/link} und sein Hexendoktor, {link:nezzliok-the-dire}Nezzliok der Schreckliche{/link}, hausen tief in den Ruinen, und ihre Kopfjäger streifen die Küste entlang bis zu den Ruinen von Zuuldaia. Zwei gemeißelte Tafeln alter Trolllegenden stehen noch zwischen den zerbrochenen Steinen. Wer kommt, um sie abzuschreiben, verweilt selten lange.]=],
		},
	},
})

Translate("deDE", "ruins-of-zul-mamwe", {
	title = "Ruinen von Zul'Mamwe",
	aliases = { "Zul'Mamwe" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Mitten im Dschungel, östlich der Arena der Gurubashi, liegen die Lande des Stammes der Skullsplitter. Ihre Dörfer stehen in den Ruinen von Balia'mah, Ziata'jai und Zul'Mamwe, und jedes hütet einen Haufen Trophäenschädel, die seinen Feinden abgenommen wurden. Die Skullsplitter führen Krieg gegen die Bloodscalp im Norden und gegen das Andenken der {link:darkspear-trolls}Darkspear{/link}. Ihr Häuptling ist Ana'thek der Grausame, und ihr Hexendoktor, Mogh, wird der Unsterbliche genannt. Ihre Hauer sind groß und schön, und manche Goblins haben eine Verwendung für sie gefunden, die den Käufern von Tigerzähnen nicht gefallen würde.]=],
		},
	},
})

Translate("deDE", "mizjah-ruins", {
	title = "Ruinen von Mizjah",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Ruinen von Mizjah liegen südöstlich von {link:grom-gol-base-camp}Grom'gol{/link}, jenseits des Flusses. Einst waren sie eine Trollsiedlung. Jetzt hat eine Ogerbande sie eingenommen, und von ihren Mauern aus fallen die {link:ogres}Oger{/link} über die Nachschubkarawanen der {link:horde}Horde{/link} auf der Dschungelstraße her. Die Warnungen Grom'gols blieben ungehört, und dem Kommandanten des Lagers ist die Geduld ausgegangen. Jenseits des Flusses, gegenüber den Ruinen, schleichen Panther und Tigerinnen durch das Unterholz.]=],
		},
	},
})

Translate("deDE", "mosh-ogg-ogre-mound", {
	title = "Ogerhügel der Mosh'Ogg",
	aliases = { "Mosh'Ogg", "Mosh'Ogg-Oger" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Ogerhügel der Mosh'Ogg liegt in den östlichen Bergen des Schlingendorntals, nicht weit südlich von {link:zul-gurub}Zul'Gurub{/link}. Er ist die Festung des Klans der Mosh'Ogg, eines Klans von {link:ogres}Ogern{/link}: Zerfleischer, Kriegstreiber, Schamanen und Fürsten. Tief im Inneren hauste der Ogermagier {link:mai-zoth}Mai'Zoth{/link}, der den Dschungel aus den Tagen kannte, als die {link:darkspear-trolls}Darkspear{/link} noch darin lebten. Die Mosh'Ogg spielen auch gern um Einsätze, und sie verlieren nicht gern. Ein Mensch, der ihnen einst zu viel abgewann, wurde mitsamt seinem Gewinn aus dem Hügel gejagt.]=],
		},
	},
})

Translate("deDE", "lake-nazferiti", {
	title = "Der Nazferitisee",
	aliases = { "Nazferiti", "Stützpunkt der Venture Co." },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Nazferitisee liegt im Norden des Dschungels, und an seinen Ufern hat die {link:venture-company}Venture Company{/link} einen Stützpunkt errichtet. Ihre Schredder fällen den Wald, und ihre Geologen graben in den Hügeln nach seltsamen blauen Kristallen. Der Vorarbeiter, Cozzle, hält seine Pläne in seinem Haus unter Verschluss. Die Venture Company hat im {link:stranglethorn-vale}Schlingendorntal{/link} keine Freunde. Die Händler von {link:booty-bay}Booty Bay{/link} hassen sie, {link:the-baron}der Baron{/link} hat Agenten auf sie angesetzt, und der Dschungel selbst scheint sich ihr zu widersetzen.]=],
		},
	},
})

Translate("deDE", "crystalvein-mine", {
	title = "Kristalladermine",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Kristalladermine liegt in den Hügeln südöstlich von {link:grom-gol-base-camp}Grom'gol{/link}. Ihre Wände bergen die singenden Kristalle, die es nirgends außer im {link:stranglethorn-vale}Schlingendorntal{/link} gibt, und sie wimmelt von Basilisken. Die Tiere fressen den Kristall, und er härtet ihre Haut, sodass ein erlegter Basilisk Splitter liefern kann, die so fein sind wie jeder aus dem Fels gegrabene. Die {link:venture-company}Venture Company{/link} kommt wegen der Basilisken nicht in die Mine, und so gräbt sie den Kristall stattdessen aus den Hügeln ringsum. Man sagt, die Splitter singen für jene, die sie hören können.]=],
		},
	},
})

Translate("deDE", "the-vile-reef", {
	title = "Das finstere Riff",
	aliases = { "Finsteres Riff" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das finstere Riff liegt unter den Wassern der ungezähmten Küste, nordwestlich von {link:grom-gol-base-camp}Grom'gol{/link}. Vor langer Zeit ließ ein gewaltiges Beben der Erde hier eine Trollstadt versinken, und ihre Straßen liegen nun unter dem Meer. Die {link:trolls}Trolle{/link} gaben dem Ort seinen Namen, weil {link:murlocs}Murlocs{/link} in den ertrunkenen Ruinen hausen und jeden angreifen, der sich nähert. Zwischen den Ruinen steht eine Steintafel, die die Geschichte von Gri'lek erzählt, einem Helden der Trolllegenden. Die {link:darkspear-trolls}Darkspear{/link} halten die Geschichte heilig.]=],
		},
	},
})

Translate("deDE", "nek-mani-wellspring", {
	title = "Nek'maniquellbrunnen",
	aliases = { "die heilige Quelle" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Hoch auf den Klippen der Westküste, südlich der Arena der Gurubashi, liegt eine Quelle, die die Gelehrten heilig nennen. Niemand ist sich einig, wem sie gehört. Jedes Volk Azeroths, sagen die Schamanen, behauptet, ihr Wasser sei allein für es gesegnet worden, und Priester und Mystiker streiten darüber, solange man denken kann. Nun ist eine Expedition der {link:naga}Naga{/link} aus dem Meer heraufgekommen und hat die Quelle eingenommen. Was die Naga mit ihr wollen, hat niemand in Erfahrung gebracht.]=],
		},
	},
})

Translate("deDE", "the-cape-of-stranglethorn", {
	title = "Kap des Schlingendorntals",
	aliases = { "Kap des Schlingendorns" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Kap des Schlingendorntals ist das südliche Ende des Dschungels, wo sich das Land zwischen zwei Meeren gen {link:booty-bay}Booty Bay{/link} verengt. Große Affen streifen durch das Nebeltal östlich des Hafens. An der Ostküste des Kaps, dem Kristallufer, stehen die {link:ruins-of-aboraz-and-jubuwal}Ruinen von Aboraz und Jubuwal{/link}, wo der ausgestoßene {link:zanzil-the-outcast}Zanzil{/link} seine Anhänger hält. In einer verborgenen Höhle auf dem südlichen Kap lebt ein Hexendoktor, der mit den Geistern spricht. Die Piraten der Blutsegel sind im Süden an den wilden Ufern gelandet. Das Kap ist der geschäftigste Winkel des Schlingendorntals und einer der gefährlichsten.]=],
		},
	},
})

Translate("deDE", "ruins-of-aboraz-and-jubuwal", {
	title = "Ruinen von Aboraz und Jubuwal",
	aliases = { "Ruinen von Aboraz", "Ruinen von Jubuwal", "Aboraz", "Jubuwal" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Nordöstlich von {link:booty-bay}Booty Bay{/link}, am Kristallufer, stehen zwei verfallene Trollsiedlungen: Aboraz und Jubuwal. Sie sind das Reich von {link:zanzil-the-outcast}Zanzil{/link} dem Ausgestoßenen, einem Hexendoktor, den sein eigener Stamm verstoßen hat. Seine Anhänger leben von seinem Gebräu und stellen ihn nicht in Frage. Auch die Toten wandeln hier. Drei Spieler aus Booty Bay, die ihre Schulden nicht bezahlen konnten, irren nun verflucht und verhext durch diese Ruinen. Unter Zanzils Sklaven war einst ein junger {link:darkspear-trolls}Darkspear{/link}, der verlorene Sohn eines Häuptlings.]=],
		},
	},
})

Translate("deDE", "jaguero-isle", {
	title = "Die Insel Jaguero",
	aliases = { "Insel Jaguero" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Insel Jaguero liegt vor der Südostküste des Kaps. Sie ist wild und dicht bewachsen, und ihre Tiere gehorchen einem großen Affen namens König Mukla. Panther streifen an ihren Ufern umher. Wenige Seeleute legen hier an, und wer es tut, findet keinen Hafen. Von den Stränden der Insel aus sieht man an klaren Tagen im Nordwesten die wilden Ufer und im Südwesten die hohen Schiffe der Piraten. Auch eine Gefangene sah sie einst und warf eine Botschaft ins Meer.]=],
		},
	},
})

Translate("deDE", "wild-shore", {
	title = "Die wilden Ufer",
	aliases = { "Truppenlager der Blutsegelbukaniere", "die Crimson Veil" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die wilden Ufer sind die südlichste Küste des Schlingendorntals, jenseits der Klippen von {link:booty-bay}Booty Bay{/link}. Hier haben die {red:bloodsail-buccaneers}Blutsegelbukaniere{/red} ein Truppenlager errichtet, das sie ihren südlichen Kommandoposten nennen. Vor der Küste liegen drei ihrer Schiffe vor Anker: die {i}Crimson Veil{/i}, die {i}Riptide{/i} und die {i}Damsel's Luck{/i}. Unter Deck der {i}Crimson Veil{/i} plant {link:fleet-master-firallon}Flottenmeister Firallon{/link} seinen Krieg gegen Booty Bay. Die Küste ist kein Ort für jemanden, der nicht die Farben der Blutsegel führt.]=],
		},
	},
})

Translate("deDE", "green-hills-of-stranglethorn", {
	title = "Green Hills of Stranglethorn",
	found = [=[Seine Seiten sind über den Dschungel verstreut; Barnil Stonepot sammelt sie in Nesingwarys Expedition]=],
	aliases = { "The Green Hills of Stranglethorn" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[{i}Green Hills of Stranglethorn{/i} ist das Buch über {link:hemet-nesingwary}Hemet{/link} Nesingwarys Jagden im Dschungel, von eigener Hand geschrieben. Sein Gefährte {link:barnil-stonepot}Barnil Stonepot{/link} las es für ihn gegen, als ein Windstoß die Seiten über das ganze {link:stranglethorn-vale}Schlingendorntal{/link} verstreute. Das Buch besteht aus vier Kapiteln. Das erste schildert den Schauplatz und nennt die Gefährten des Jägers. Das zweite ist voller Geschichten von Tigern und Panthern. Das dritte erzählt von der ersten Beute, die {link:sir-s-j-erlgadin}Sir Erlgadin{/link} und {link:ajeck-rouack}Lady Rouack{/link} mit einem Zwergengewehr erlegten, und endet in Spannung. Das vierte ist das große Finale. Barnil hofft, es eines Tages in Bibliotheken auf der ganzen Welt zu sehen.]=],
		},
	},
})

Translate("deDE", "baron-revilgaz", {
	title = "Baron Revilgaz",
	subtitle = "Herr von Booty Bay",
	found = [=[Booty Bay, im obersten Stockwerk der Taverne jenseits des Hafens]=],
	hint = [=[Steigt ganz nach oben in die Taverne, die über den Hafen von Booty Bay blickt.]=],
	allegiance = "Booty Bay · Steamwheedle-Kartell",
	aliases = { "Revilgaz" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Baron Revilgaz ist der Goblinherr von {link:booty-bay}Booty Bay{/link}. Vom obersten Stockwerk der Taverne aus wacht er über den Hafen, die Schiffe, den Handel und die Streitigkeiten des Hafens. Sein eigenes Volk nennt ihn den berüchtigtsten Piraten der Küste, und niemand, der ihn kennt, bezweifelt es. Er ist reich, stolz, und es ist gefährlich, sich ihm in den Weg zu stellen. Außerdem sammelt er die alten Relikte der Trollreiche, und er ist bereit, viel von der Zeit anderer Leute aufzuwenden, um seinen Regalen eines hinzuzufügen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Revilgaz ist das Gesetz von {link:booty-bay}Booty Bay{/link}. Die Blutsegelbukaniere wissen, dass sie sich dem Hafen zu seinen Bedingungen fügen müssen, solange er lebt, und sie würden teuer dafür bezahlen, ihn tot zu sehen. Seine Agenten beobachten die {link:venture-company}Venture Company{/link}, zu seinen Freunden zählen Erzmagier der {link:kirin-tor}Kirin Tor{/link}, und sein Geld reicht bis zu den Rennbahnen Kalimdors.]=],
		},
		{
			title = "Taten",
			text = [=[• Er herrscht über {link:booty-bay}Booty Bay{/link} und hält den Hafen für jedes Schiff offen, das zahlt.
• Er hält sich Agenten wie {link:kebok}Kebok{/link} und {link:krazek}Krazek{/link}, die ihm Gerüchte zutragen und seine Probleme still aus der Welt schaffen.
• Er befahl Kebok, sich um einen Goblin zu kümmern, der begonnen hatte, die Magnaten der Handelsprinzen beiseitezudrängen.
• Er fördert den Goblinrennfahrer {link:pozzik}Pozzik{/link} und ließ in dessen Namen die Pläne eines Brennstoffreglers der {link:venture-company}Venture Company{/link} beschaffen.
• Er hatte schon früher mit dem Erzmagier {link:archmage-ansirem-runeweaver}Ansirem Runeweaver{/link} aus {link:dalaran}Dalaran{/link} zu tun.]=],
		},
	},
	chapters = {
		{
			title = "Der Stein der Gezeiten",
			hint = [=[Bringt dem Baron Kunde von der Spukinsel und folgt, wohin sie führt.]=],
			text = [=[Seeleute in der Taverne sprachen von einer Insel vor der Küste, heimgesucht von Wasserelementaren und dem Geist eines tobenden Goblins. {link:krazek}Krazek{/link} gab die Geschichte weiter, und Revilgaz erinnerte sich an eine Trolllegende, die er einst gelesen hatte: den Stein der Gezeiten, ein Relikt, das seinen Träger verflucht, aus der Welt zu schwinden und wieder in sie zurückzukehren. Ein Goblinzauberer namens Gazban soll ihn gefunden haben. Revilgaz wollte {link:booty-bay}Booty Bay{/link} nicht verlassen, um selbst mit lästigen Magiern zu reden, also schickte er die Armschienen der Elementare nach {link:dalaran}Dalaran{/link}. {link:archmage-ansirem-runeweaver}Ansirem{/link} fand die Spur des Fluchs, und einen Trolldolch, um ihn zu brechen. Der Stein hat nun einen Ehrenplatz in der Sammlung des Barons.]=],
		},
		{
			title = "Die Gunst eines Förderers",
			hint = [=[Sucht im Namen eines Goblinrennfahrers der schimmernden Ebene die Hilfe des Barons.]=],
			text = [=[Dem Goblinrennfahrer {link:pozzik}Pozzik{/link} war ein neuer Brennstoffregler aus {link:booty-bay}Booty Bay{/link} versprochen worden, und er kam nie an. Die Schredder der {link:venture-company}Venture Company{/link} am Nazferitisee nutzten die neue Bauart, und ihr Vorarbeiter hielt die Baupläne unter Verschluss. Revilgaz wollte sie abgeschrieben haben, um Pozziks willen und für seine eigenen Aufzeichnungen. Er mag es nicht, wenn seine Rennfahrer glauben, ihre Förderer hätten sie im Stich gelassen.]=],
		},
	},
	mentions = {
		{ text = "Die Spukinsel" },
		{ text = "Der Stein der Gezeiten" },
		{ text = "Wasserelementare" },
		{ text = "Magische Analyse" },
		{ text = "Der Fluch der Gezeiten" },
		{ text = "Goblinförderung" },
		{ text = "Goblinförderung" },
		{ text = "Goblinförderung" },
		{ text = "Feindliche Übernahme" },
		{ text = "Ahoi, Admiral!" },
	},
	bonds = {
		{ id = "krazek", name = "Krazek", note = "trägt ihm Gerüchte zu" },
		{ id = "kebok", name = "Kebok", note = "sein Agent in Booty Bay" },
		{ id = "archmage-ansirem-runeweaver", name = "Erzmagier Ansirem Runeweaver", note = "der Magier, der den Fluch entschlüsselte" },
		{ id = "catelyn-the-blade", name = "Catelyn die Klinge", note = "lieh seiner Sache ihren Dolch" },
		{ id = "fleet-master-seahorn", name = "Flottenmeister Seahorn", note = "Meister der Flotte, die den Hafen schützt" },
		{ id = "fleet-master-firallon", name = "Flottenmeister Firallon", note = "will ihn tot sehen" },
	},
})

Translate("deDE", "hemet-nesingwary", {
	title = "Hemet Nesingwary",
	subtitle = "Jäger großer Bestien",
	found = "Nesingwarys Expedition, im Norden des Dschungels",
	hint = [=[Sucht den zwergischen Jäger, dessen Lager flussaufwärts vom Nazferitisee steht.]=],
	allegiance = "Nesingwarys Expedition · Allianz",
	aliases = { "Nesingwary", "Hemet Nesingwary Jr.", "Meister Nesingwary", "Hemet" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Hemet Nesingwary ist ein {link:dwarves}Zwerg{/link}, ein Jäger und ein Erzähler von Jagdgeschichten. Seine Gefährten nennen ihn einen berühmten Helden der {link:alliance}Allianz{/link}, und er kämpfte auf den Schlachtfeldern von {link:lordaeron}Lordaeron{/link}, bevor er das Gewehr zum Vergnügen ergriff. Er hat überall auf der Welt gejagt. Nun ist er mit einer Schar anderer Jäger ins {link:stranglethorn-vale}Schlingendorntal{/link} gekommen, und vor allem eine Bestie hat ihn hergelockt: der weiße Tiger {link:king-bangalash}König Bangalash{/link}.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Nesingwary ist berühmt, reich und hat gute Verbindungen. Selbst die Goblins von {link:booty-bay}Booty Bay{/link} achten darauf, zu erfahren, was er treibt. Er ist stolz auf sein Können und großzügig gegenüber jedem, der es ihm gleichtun kann, gleich welcher Rasse oder welchen Banners. Er hat die Geschichte seiner Jagden im Dschungel niedergeschrieben, und seine Gefährten hoffen, dass sie überall auf der Welt gelesen wird.]=],
		},
		{
			title = "Taten",
			text = [=[• Er schlug sein Lager am nördlichen Fluss mit {link:barnil-stonepot}Barnil Stonepot{/link}, {link:ajeck-rouack}Ajeck Rouack{/link} und {link:sir-s-j-erlgadin}Sir S. J. Erlgadin{/link} auf.
• Er prüft Neuankömmlinge in der Raptorenjagd, während Ajeck sie an Tigern misst und Sir Erlgadin an Panthern.
• Er jagte die Bestien von {link:desolace}Desolace{/link} mit dem {link:tauren}Tauren{/link} {red:roon-wildmane}Roon Wildmane{/red}, und die beiden wurden trotz der alten Feindschaft ihrer Völker Freunde.
• Er bestellte bei einem Goblin der schimmernden Ebene eine Kiste Spezialmunition, bevor er in den Dschungel aufbrach.
• Er schrieb {i}{link:green-hills-of-stranglethorn}Green Hills of Stranglethorn{/link}{/i}, die Geschichte seiner Jagden.]=],
		},
	},
	chapters = {
		{
			title = "Die Meister der Jagd",
			hint = "Beweist Euch gegen die Raptoren des Dschungels.",
			text = [=[Die Jäger des Lagers teilen ihr Feuer nicht mit jedem. Hemet stellt seine Prüfungen klar: zuerst Raptoren, dann die flinkeren Arten, dann die Dschungelpirscher, die am schwersten von allen aufzuspüren sind. Die letzte Prüfung ist eine Raptorin namens Tethis, die Hemet selbst nie erlegt hat. Wer ihre Klaue zurückbringt, wird zum Meister der Raptorenjagd ernannt.]=],
		},
		{
			title = "Der weiße Tiger",
			hint = [=[Jagt die Bestie, die Nesingwary ins Schlingendorntal geführt hat.]=],
			text = [=[Als Sin'Dall, Bhag'thera und Tethis gefallen waren, gab Hemet den wahren Grund seines Kommens preis. Nicht ihretwegen hatte er das Meer überquert. Er war wegen {link:king-bangalash}König Bangalash{/link} gekommen, dem weißen Tiger, der ihn mehr als einmal humpelnd ins Lager zurückgeschickt hatte. Als der Tiger erlegt war, ließ Hemet den Jäger hochleben, der vollbracht hatte, was ihm selbst nicht gelungen war, und ernannte ihn zum Gefährten der Expedition.]=],
		},
		{
			title = "Alte Freunde",
			hint = "Bringt dem Jäger ein Geschenk von einem fernen Freund.",
			text = [=[Noch immer finden Geschenke ihren Weg über das Meer ins Lager. Ein Goblinhändler der schimmernden Ebene schickte eine Kiste Munition, die Hemet längst bezahlt hatte. Ein Taure aus {link:desolace}Desolace{/link} sandte ein Kodohorn und damit eine Einladung, noch einmal gemeinsam zu jagen. Hemet freute sich über beides. Vorerst ist er tief im Dschungel, doch das Land der {link:centaurs}Zentauren{/link} hat er nicht vergessen.]=],
		},
	},
	mentions = {
		{ text = "Willkommen im Dschungel" },
		{ text = "Raptorenmeisterschaft" },
		{ text = "Raptorenmeisterschaft" },
		{ text = "Raptorenmeisterschaft" },
		{ text = "Raptorenmeisterschaft" },
		{ text = "Großwildjäger" },
		{ text = "Hemet Nesingwary" },
		{ text = "Jagd im {link:stranglethorn-vale}Schlingendorntal{/link}" },
		{ text = "Untersucht das Lager" },
		{ text = "Die grünen Hügel des Schlingendorntals" },
	},
	bonds = {
		{ id = "barnil-stonepot", name = "Barnil Stonepot", note = "sein Gefährte und Korrekturleser" },
		{ id = "ajeck-rouack", name = "Ajeck Rouack", note = "seine Gefährtin, Meisterin der Tigerjagd" },
		{ id = "sir-s-j-erlgadin", name = "Sir S. J. Erlgadin", note = "sein Gefährte, Meister der Pantherjagd" },
		{ id = "king-bangalash", name = "König Bangalash", note = "die Beute, derentwegen er kam" },
		{ id = "roon-wildmane", name = "Roon Wildmane", note = "sein Jagdfreund aus Desolace" },
		{ id = "krazek", name = "Krazek", note = "beobachtet sein Lager für die Goblins" },
	},
})

Translate("deDE", "lieutenant-doren", {
	title = "Leutnant Doren",
	subtitle = "Anführer der Rebellen",
	found = "Das Rebellenlager, im äußersten Norden des Dschungels",
	hint = [=[Sucht den Offizier, der die Rebellen nahe der Straße aus dem Dämmerwald anführt.]=],
	allegiance = "Königreich Stormwind · Rebellenlager",
	aliases = { "Doren" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Leutnant Doren befehligt die Rebellen des Schlingendorntals. Er und seine Soldaten dienten einst {link:colonel-kurzen}Oberst Kurzen{/link} und waren ihm leidenschaftlich treu. Dann veränderte sich der Oberst. Als Kurzen in Grausamkeit versank, wurde die Ergebenheit seiner Männer zu Zorn, und Doren führte jene, die ihm nicht länger folgen wollten, in ein eigenes Lager. Seitdem liegen sie im Krieg mit ihrem alten Kommandanten.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Doren führt einen Krieg, den er allein nicht gewinnen kann. {link:colonel-kurzen}Kurzen{/link} ist ein brillanter Taktiker, und seine Männer sind den Rebellen um ein Vielfaches überlegen. Die Rebellen überleben mit Vorräten der Goblins, mit gestohlener Medizin und mit Geheimnissen. Doren muss diese Geheimnisse gut hüten, denn ein einziges Wort im falschen Ohr könnte seinen Soldaten ein Messer an die Kehle setzen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er hält das {link:rebel-camp}Rebellenlager{/link} gegen die Truppen des Obersts.
• Er schickte Gefreiten {link:private-thorsen}Thorsen{/link} als Spion zurück unter Kurzens Männer.
• Er suchte die Aufzeichnungen von Bookie {link:herod}Herod{/link}, Kurzens Vorratsverwalter, um herauszufinden, wie Thorsens Geheimnis verraten wurde.
• Er fand den Verräter in seinem eigenen Lager.
• Er schickte einen Streiter in das Vorratslager, um dem Oberst selbst gegenüberzutreten.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Kein Bericht erzählt, wie Dorens Kompanie in den Dienst im {link:stranglethorn-vale}Schlingendorntal{/link} kam oder wann die Rebellen mit ihrem Oberst brachen.]=],
		},
	},
	chapters = {
		{
			title = "Der Verräter im Lager",
			hint = [=[Helft dem Leutnant herauszufinden, wer seinen Spion verraten hat.]=],
			text = [=[Nur drei wussten von Thorsens Auftrag: Doren, {link:sergeant-yohwa}Sergeant Yohwa{/link} und {link:private-thorsen}Thorsen{/link} selbst. Doch auch Kurzens Männer hatten davon gewusst. In Bookie Herods Geldkassette lag ein schmutziger Zettel, der Thorsens Streifengänge, seine Freunde und seine Gewohnheiten auflistete, unterzeichnet mit einem einzigen Buchstaben. Die Wachpläne verrieten den Rest. Der Mann, der die ganze Woche Thorsens Wache geteilt hatte, war Gefreiter Merle. Doren hatte ihn für einen tapferen Soldaten mit aufrichtigem Herzen gehalten. Die Entdeckung schmerzte ihn, und noch mehr erleichterte sie ihn.]=],
		},
		{
			title = "Der Fall des Obersts",
			hint = "Tragt die Hoffnung der Rebellen in das Vorratslager.",
			text = [=[Als die Dschungelkämpfer des Obersts ausgedünnt und seine Spezialeinheiten zerschlagen waren, bat Doren um die letzte und schwerste Tat. Wer für die Rebellen gekämpft hatte, sollte in das Vorratslager eindringen, an Kurzens Verteidigern vorbeigelangen und dem Oberst und seinen Hauptleuten gegenübertreten. Doren konnte den Bericht kaum glauben, als er eintraf. Zum ersten Mal seit Beginn der Rebellion konnten seine Soldaten aufatmen.]=],
		},
	},
	mentions = {
		{ text = "Dschungelgeheimnisse" },
		{ text = "Bookie {link:herod}Herod{/link}" },
		{ text = "Der Spion ist enttarnt!" },
		{ text = "Wachpläne" },
		{ text = "Meldet Euch bei Doren" },
		{ text = "Spezialeinheiten" },
		{ text = "{link:colonel-kurzen}Oberst Kurzen{/link}" },
	},
	bonds = {
		{ id = "colonel-kurzen", name = "Oberst Kurzen", note = "sein früherer Kommandant und Feind" },
		{ id = "sergeant-yohwa", name = "Sergeant Yohwa", note = "seine Sergeantin, der er vertraut" },
		{ id = "private-thorsen", name = "Gefreiter Thorsen", note = "sein Spion" },
		{ id = "brother-nimetz", name = "Bruder Nimetz", note = "sucht die Ursache für Kurzens Fall" },
		{ id = "krazek", name = "Krazek", note = "schickt dem Lager seine Vorräte" },
	},
})

Translate("deDE", "nimboya", {
	title = "Nimboya",
	subtitle = "Gesandter der Darkspear",
	found = "Das Basislager von Grom'gol",
	hint = [=[Sprecht mit dem Troll der Darkspear in Grom'gol, der nach einem verlorenen Sohn seines Stammes sucht.]=],
	allegiance = "Darkspear · Horde",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Nimboya ist ein Troll vom Stamm der {link:darkspear-trolls}Darkspear{/link}, aus dem fernen {link:orgrimmar}Orgrimmar{/link} ins {link:stranglethorn-vale}Schlingendorntal{/link} zurückgesandt. Seine Aufgabe ist ernst. Nach einem alten Brauch seines Volkes wurde der jüngste Sohn seines Häuptlings, {link:yenniku}Yenniku{/link}, den Gurubashitrollen von {link:zul-gurub}Zul'Gurub{/link} übergeben. Als die Darkspear den Dschungel verließen, um {link:thrall}Thrall{/link} zu folgen, blieb der Junge zurück und ging verloren. Nimboya ist gekommen, um ihn zu finden, lebendig oder tot.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Nimboya spricht für die {link:darkspear-trolls}Darkspear{/link} in dem Land, das sie einst ihre Heimat nannten. Durch ihn verfolgt der Stamm seine ältesten Fehden und seine neuesten Pflichten gegenüber der {link:horde}Horde{/link}: die Suche nach {link:yenniku}Yenniku{/link}, den Krieg gegen die Bloodscalp, die Bestrafung der {link:witherbark-village}Witherbark{/link}, die den Kriegshäuptling verrieten, und den Plan {link:vol-jin}Vol'jin{/link}s, das Schwert {link:trol-kalar}Trol'kalar{/link} zu gewinnen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er jagte den Stamm der Bloodscalp nach einer Spur von {link:yenniku}Yenniku{/link}.
• Er untersuchte sehr viele Schrumpfköpfe und dankte den Geistern, als der des Jungen nicht darunter war.
• Mit einem brodelnden Kessel zwang er den abgetrennten Köpfen des Bloodscalphäuptlings und seines Hexendoktors die Wahrheit ab.
• Er schickte seinen Spieß nach Norden ins {link:the-hinterlands}Hinterland{/link}, als grimmige Botschaft an die {link:witherbark-trolls}Witherbarktrolle{/link}.
• Er weist den Streitern der {link:horde}Horde{/link} den Weg nach {link:hammerfall}Hammerfall{/link} und zum Jäger {link:zengu}Zengu{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Die Köpfe, die sprachen",
			hint = [=[Bringt die Köpfe des Bloodscalphäuptlings und seines Hexendoktors zu Nimboyas Kessel.]=],
			text = [=[Nimboya fürchtete, die Bloodscalp hätten den Jungen getötet, und er schwor ihrem Häuptling für diesen Fall einen Fluch von sechshundert Jahren. Die Köpfe von {link:gan-zulah}Gan'zulah{/link} und {link:nezzliok-the-dire}Nezzliok{/link} kamen in seinen Kessel, und die Toten sprachen. Selbst da feilschten sie noch und verlangten Trophäen und Blut, bevor sie antworten wollten. Schließlich sagte Nezzliok die Wahrheit. {link:yenniku}Yenniku{/link} lebte, doch er gehörte nicht mehr sich selbst. Der Hexendoktor {link:zanzil-the-outcast}Zanzil der Ausgestoßene{/link} hielt ihn, mit Leib und Seele.]=],
		},
		{
			title = "Yenniku retten",
			hint = "Bringt den verlorenen Sohn der Darkspear heim.",
			text = [=[Danach war die Hoffnung schwach, so klein wie das kleinste Insekt, sagte Nimboya. Doch {link:kin-weelay}Kin'weelay{/link} erfuhr von den Geistern, wo das Auge des Geistes lag. Es wurde dem {link:ogres}Oger{/link} {link:mai-zoth}Mai'Zoth{/link} entrissen, und der Hexendoktor formte es zu einem Edelstein um, der eine Seele fassen konnte. Damit wurde {link:yenniku}Yenniku{/link} betäubt und sein Geist Zanzils Griff entrissen, und der Stein wurde nach {link:grom-gol-base-camp}Grom'gol{/link} gebracht. Nimboya hatte seine Mission für hoffnungslos gehalten. Er versprach, dass der Stamm von der Tat singen und sie in Stein meißeln werde.]=],
		},
	},
	mentions = {
		{ text = "Die Jagd nach {link:yenniku}Yenniku{/link}" },
		{ text = "Kopfjagd" },
		{ text = "Köpfe des Bloodscalpklans" },
