	},
	bonds = {
		{ id = "yenniku", name = "Yenniku", note = "der Häuptlingssohn, den er sucht" },
		{ id = "kin-weelay", name = "Kin'weelay", note = "sein Mitgesandter" },
		{ id = "gan-zulah", name = "Gan'zulah", note = "von ihm verflucht" },
		{ id = "nezzliok-the-dire", name = "Nezzliok der Schreckliche", note = "sprach aus dem Kessel" },
