Translate("deDE", "zanzil-the-outcast", {
	title = "Zanzil der Ausgestoßene",
	subtitle = "Der verbannte Hexendoktor",
	found = "Die Ruinen von Aboraz, am Kristallufer",
	hint = [=[Sucht den ausgestoßenen Hexendoktor in den Ruinen nordöstlich von Booty Bay.]=],
	allegiance = "Seine eigenen Anhänger",
	aliases = { "Zanzil" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Zanzil ist ein Hexendoktor der {link:trolls}Trolle{/link}, den sein eigener Stamm verstoßen hat. Seine Anführer fürchteten ihn, und das zu Recht. Er weiß, wie man den Geist anderer beugt. Aus den Pflanzen des Dschungels braut er ein Gemisch, das den Willen derer lähmt, die es trinken, und ihre Körper stark macht, und seine Anhänger in den {link:ruins-of-aboraz-and-jubuwal}Ruinen von Aboraz und Jubuwal{/link} leben davon. Auch die Toten, die dort umherwandern, verdanken ihren Zustand womöglich ihm.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Zanzils Kunst hat sich über den Dschungel hinaus verbreitet. Die Goblins von {link:booty-bay}Booty Bay{/link} kaufen Proben seines Gemischs, und einer von ihnen hat gelernt, daraus ein starkes Getränk für eigene Pläne zu brauen. Weit im Norden haben die Spione von {link:si-7}SI:7{/link} erfahren, dass Zanzils {link:trolls}Trolle{/link} wissen, wie man mit Gift die Toten erweckt, und dass das Geheimnis in die Hände der {link:defias-brotherhood}Bruderschaft der Defias{/link} gelangt ist. In {link:tarren-mill}Tarrens Mühle{/link} hat {link:serge-hinott}Serge Hinott{/link} den Wahnsinn untersucht, den seine Gifte bringen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er wurde von seinem Stamm wegen seiner Macht über den Geist anderer verbannt.
• Er führt seine Anhänger in den {link:ruins-of-aboraz-and-jubuwal}Ruinen von Aboraz und Jubuwal{/link}.
• Er nahm den Darkspearjungen {link:yenniku}Yenniku{/link} und hielt ihn mit Leib und Seele gefangen.
• Man sagt, seine Gebräue erwecken die Toten.]=],
		},
	},
	chapters = {
		{
			title = "Das Gemisch",
			hint = "Nehmt Zanzils Anhängern das Gebräu ab, das sie bindet.",
			text = [=[{link:crank-fizzlebub}Crank Fizzlebub{/link} erklärte die Sache ohne Umschweife jedem, der zuhören wollte. Ein Gemisch, das den Willen unterdrücken und den Körper härten kann, ist viel wert für jene, die über andere herrschen wollen. Er zahlte gut dafür, und ein wenig mehr für Verschwiegenheit.]=],
		},
		{
			title = "Die gestohlene Seele",
			hint = "Befreit den jungen Darkspear aus dem Griff des Hexendoktors.",
			text = [=[Zanzils Macht über {link:yenniku}Yenniku{/link} war so stark, dass nur die mächtigste Magie sie brechen konnte. Die Hexendoktoren der {link:darkspear-trolls}Darkspear{/link} schufen diese Magie aus dem Juwel eines Ogers. Als sich der Seelenstein um Yennikus Geist schloss, verlor Zanzil den kostbarsten seiner Sklaven.]=],
		},
	},
	mentions = {
		{ text = "Zanzils Geheimnis" },
		{ text = "Yennikus Schicksal" },
		{ text = "{link:yenniku}Yenniku{/link} retten" },
		{ text = "Zurück nach {link:booty-bay}Booty Bay{/link}" },
		{ text = "Zanzils Gemisch und ein Narrenstout" },
		{ text = "Voodooschulden" },
		{ text = "Klavens Turm" },
	},
	bonds = {
		{ id = "yenniku", name = "Yenniku", note = "sein Sklave" },
		{ id = "crank-fizzlebub", name = "Crank Fizzlebub", note = "kauft sein Gemisch" },
		{ id = "nimboya", name = "Nimboya", note = "will ihm Yenniku entreißen" },
		{ id = "agent-kearnen", name = "Agent Kearnen", note = "deckte die Spur des Gifts auf" },
		{ id = "serge-hinott", name = "Serge Hinott", note = "heilt sein Gift" },
	},
})

Translate("deDE", "fleet-master-seahorn", {
	title = "Flottenmeister Seahorn",
	subtitle = "Flottenmeister der Schwarzmeerräuber",
	found = "Booty Bay, nahe den Gemächern des Barons",
	hint = [=[Sucht den alten Seebären, der in Booty Bay die Flotte der Schwarzmeerräuber befehligt.]=],
	allegiance = "Schwarzmeerräuber · Booty Bay",
	aliases = { "Seahorn" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Flottenmeister Seahorn befehligt die Schiffe der {red:blackwater-raiders}Schwarzmeerräuber{/red}, der Piraten, die {link:booty-bay}Booty Bay{/link} ihren Heimathafen nennen. Seine Flotte liegt jetzt im Hafen und wartet darauf, neue Vorräte aufzunehmen, während seine Kapitäne in seinem Auftrag die Meere durchstreifen. Einer von ihnen, {link:shakes-o-breen}Shakes O'Breen{/link}, ist nach Norden an die Küste von {link:arathi-highlands}Arathi{/link} gezogen, einem versunkenen Elfenschatz hinterher. Seahorn ist ein alter Seebär, stolz auf seine Flotte und voller Verachtung für seine Rivalen. Seine Rivalen von den Blutsegeln hätten ihn gern tot.]=],
		},
	},
	chapters = {
		{
			title = "Die Verschwörung der Blutsegel",
			hint = [=[Findet heraus, was die Blutsegelbukaniere gegen Booty Bay planen.]=],
			text = [=[Erster Maat Crazz fand in einem Beiboot nördlich des Hafens eine Karte, auf der {link:booty-bay}Booty Bay{/link} selbst rot markiert war. Die Seekarten und Befehle aus dem Posten der Blutsegel an den wilden Ufern verrieten den Rest: {link:fleet-master-firallon}Flottenmeister Firallon{/link} wollte angreifen, und seine Schiffe hatten gleich vor dem Kap Anker geworfen. Seahorn verspottete ihn als einen Mann, der kein Beiboot über einen See segeln könne. Er schickte nicht seine Flotte. Stattdessen schickte er ein paar tapfere Kämpfer, um die Anführer der Blutsegel niederzustrecken.]=],
		},
	},
	mentions = {
		{ text = "Die Blutsegelbukaniere" },
		{ text = "Die Blutsegelbukaniere" },
		{ text = "Die Blutsegelbukaniere" },
		{ text = "Versunkener Schatz" },
		{ text = "Versunkener Schatz" },
	},
	bonds = {
		{ id = "shakes-o-breen", name = "Shakes O'Breen", note = "sein Kapitän in Arathi" },
		{ id = "fleet-master-firallon", name = "Flottenmeister Firallon", note = "sein Rivale" },
		{ id = "baron-revilgaz", name = "Baron Revilgaz", note = "Herr seines Heimathafens" },
	},
})

Translate("deDE", "fleet-master-firallon", {
	title = "Flottenmeister Firallon",
	subtitle = "Flottenmeister der Blutsegelbukaniere",
	found = "Unter Deck der Crimson Veil, vor den wilden Ufern",
	hint = [=[Sucht den Piratenkapitän an Bord der Crimson Veil, die vor den wilden Ufern ankert.]=],
	allegiance = "Blutsegelbukaniere",
	aliases = { "Firallon" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Flottenmeister Firallon führt die {red:bloodsail-buccaneers}Blutsegelbukaniere{/red}. Unter Deck seines Flaggschiffs, der {i}Crimson Veil{/i}, plant er den Fall von {link:booty-bay}Booty Bay{/link}. Allein die Macht des Hafens hält seine Piraten davon ab, zu segeln, wohin sie wollen, und zu nehmen, was ihnen gefällt. Er weiß genau, wer ihm im Weg steht: {link:fleet-master-seahorn}Flottenmeister Seahorn{/link}, dessen Schiffe den Hafen schützen, und {link:baron-revilgaz}Baron Revilgaz{/link}, dessen Gesetz dort herrscht.]=],
		},
		{
			title = "Taten",
			text = [=[• Er errichtete an den wilden Ufern einen südlichen Kommandoposten und plante einen Angriff auf {link:booty-bay}Booty Bay{/link}.
• Er nimmt jeden in seine Mannschaft auf, der kein Freund des Hafens ist.
• Er verspricht den Rang eines Admirals demjenigen, der sowohl {link:fleet-master-seahorn}Seahorn{/link} als auch {link:baron-revilgaz}Revilgaz{/link} tötet.]=],
		},
	},
	mentions = {
		{ text = "Die Blutsegelbukaniere" },
		{ text = "Die Blutsegelbukaniere" },
		{ text = "Ahoi, Landratte" },
		{ text = "Ahoi, Admiral!" },
	},
	bonds = {
		{ id = "fleet-master-seahorn", name = "Flottenmeister Seahorn", note = "sein Rivale" },
		{ id = "baron-revilgaz", name = "Baron Revilgaz", note = "das Gesetz, das er brechen will" },
	},
})

Translate("deDE", "catelyn-the-blade", {
	title = "Catelyn die Klinge",
	subtitle = "Messerkämpferin von Booty Bay",
	found = "Booty Bay, nahe der Taverne",
	hint = [=[Sucht die Messerkämpferin von Booty Bay, deren Vater ein Erzmagier ist.]=],
	allegiance = "Schwarzmeerräuber · Booty Bay",
	aliases = { "Catelyn" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Catelyn ist die Tochter des Erzmagiers {link:archmage-ansirem-runeweaver}Ansirem Runeweaver{/link} aus {link:dalaran}Dalaran{/link}. Sie wollte ihr Leben nicht zwischen muffigen Büchern und steifen alten Magiern verbringen, also lief sie nach {link:booty-bay}Booty Bay{/link} davon und wurde Piratin. Sie war die beste Messerkämpferin des Hafens, bis ein Schurke der Blutsegel namens "Pretty Boy" Duncan sie bewusstlos schlug und ihr die Klinge nahm. Der Dolch war ein Trollrelikt, das ihr Vater im {link:stranglethorn-vale}Schlingendorntal{/link} gefunden und ihr geschenkt hatte. Als er zurückgebracht wurde, lieh sie ihn aus, um den Altar des Steins der Gezeiten zu finden, unter der Bedingung, dass sie ihn zurückbekäme.]=],
		},
	},
	mentions = {
		{ text = "Ansirems Schlüssel" },
		{ text = "\"Pretty Boy\" Duncan" },
		{ text = "Der Fluch der Gezeiten" },
	},
	bonds = {
		{ id = "archmage-ansirem-runeweaver", name = "Erzmagier Ansirem Runeweaver", note = "ihr Vater" },
		{ id = "baron-revilgaz", name = "Baron Revilgaz", note = "wollte den Stein, den ihr Dolch errang" },
	},
})

Translate("deDE", "crank-fizzlebub", {
	title = "Crank Fizzlebub",
	subtitle = "Händler von Booty Bay",
	found = "Booty Bay, auf den oberen Stegen",
	hint = [=[Sucht den Goblinhändler von Booty Bay, der die Venture Company nicht leiden kann.]=],
	allegiance = "Booty Bay",
