		{ text = "Zanzils Geheimnis" },
		{ text = "Zurück nach {link:booty-bay}Booty Bay{/link}" },
		{ text = "Zanzils Gemisch und ein Narrenstout" },
		{ text = "Erstattet Fizzlebub Bericht" },
		{ text = "Narrenstout" },
	},
	bonds = {
		{ id = "zanzil-the-outcast", name = "Zanzil der Ausgestoßene", note = "die Quelle seines Gemischs" },
		{ id = "krazek", name = "Krazek", note = "ein Makler aus Booty Bay wie er" },
	},
})

Translate("deDE", "krazek", {
	title = "Krazek",
	subtitle = "Ohr des Barons",
	found = "Booty Bay, auf den oberen Stegen",
	hint = [=[Sucht den Goblin von Booty Bay, der jedes Gerücht als Erster hört.]=],
	allegiance = "Booty Bay",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Krazek ist ein Goblin aus {link:booty-bay}Booty Bay{/link}, der für den Baron die Ohren offen hält. Gerüchte über seltsame Dinge im Dschungel erreichen ihn zuerst, und die nützlichen gibt er an {link:baron-revilgaz}Revilgaz{/link} weiter. Er verkauft Geheimnisse ebenso wie Waren: für den richtigen Gefallen findet er heraus, was ein Goblinrennfahrer der schimmernden Ebene zahlen würde, um etwas verborgen zu halten. Er baut mechanische Kochtöpfe, schickt den Rebellen im Norden Vorräte und Landminen und behält die Jäger in {link:nesingwary-s-expedition}Nesingwarys Lager{/link} genau im Auge. Er hat einen Vetter, {link:tran-rek}Tran'rek{/link}, in {link:gadgetzan}Gadgetzan{/link}, der ihm eine Lieferung schuldet.]=],
		},
	},
	mentions = {
