		{ text = "{link:tran-rek}Tran'rek{/link}" },
	},
	bonds = {
		{ id = "baron-revilgaz", name = "Baron Revilgaz", note = "der Herr, dem er berichtet" },
		{ id = "lieutenant-doren", name = "Leutnant Doren", note = "die Rebellen, die er versorgt" },
		{ id = "hemet-nesingwary", name = "Hemet Nesingwary", note = "ein Jäger, den er im Auge behält" },
