Translate("deDE", "kebok", {
	title = "Kebok",
	subtitle = "Agent des Barons",
	found = "Booty Bay, auf den oberen Stegen",
	hint = [=[Sucht den geplagten Goblin, der die Geschäfte des Barons im Dschungel führt.]=],
	allegiance = "Booty Bay",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Kebok führt für {link:baron-revilgaz}Baron Revilgaz{/link} die Geschäfte im Dschungel, und sie laufen nicht gut. Die Bloodscalptrolle haben viele seiner Agenten und Wachen getötet, und die Kosten steigen immer weiter. Sein Handel mit Tigerzähnen zu den Inseln der südlichen Meere ist zu teuer, um ihn ehrlich zu beliefern, also fälscht er die Zähne stattdessen aus Hauern der Skullsplitter. Als ein Goblin der {link:venture-company}Venture Company{/link} begann, die Magnaten der Handelsprinzen beiseitezudrängen, trug {link:the-baron}der Baron{/link} Kebok auf, sich auf seine Weise darum zu kümmern. Seine Weise war Diebstahl.]=],
		},
	},
	mentions = {
		{ text = "Ohren der Bloodscalp" },
		{ text = "Hauer der Skullsplitter" },
		{ text = "Feindliche Übernahme" },
	},
	bonds = {
		{ id = "baron-revilgaz", name = "Baron Revilgaz", note = "sein Herr" },
	},
})

Translate("deDE", "sea-wolf-mackinley", {
	title = "\"Sea Wolf\" MacKinley",
	subtitle = "Spieler von Booty Bay",
	found = "Booty Bay, am Hafen",
	hint = [=[Sucht den Spieler von Booty Bay, der keine Schuld je vergisst.]=],
	allegiance = "Booty Bay",
	aliases = { "Sea Wolf MacKinley", "MacKinley", "Sea Wolf" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=["Sea Wolf" MacKinley spielt in {link:booty-bay}Booty Bay{/link} Karten und Würfel, und er gewinnt. Viele schulden ihm Geld, und er will jede Münze eintreiben. "Shaky" Phillipe ließ er mit einem Beutel Gorillainnereien so erschrecken, dass er zahlte. Drei andere Schuldner flohen in den Dschungel und kehrten verflucht daraus zurück, als wandelnde Tote in den {link:ruins-of-aboraz-and-jubuwal}Ruinen von Aboraz und Jubuwal{/link}. MacKinley wollte trotzdem, was ihm zustand. Außerdem hat er mit einem Wirt aus {link:steamwheedle-port}Steamwheedle{/link} eine Wette laufen, wessen Rum stärker ist.]=],
