		{ text = "Maurys Fuß knacken" },
		{ text = "Stoleys Schuld" },
		{ text = "Lieferung an MacKinley" },
	},
	bonds = {
		{ id = "zanzil-the-outcast", name = "Zanzil der Ausgestoßene", note = "beherrscht die Ruinen, in denen seine Schuldner umherirren" },
	},
})

Translate("deDE", "captain-hecklebury-smotts", {
	title = "Kapitän Hecklebury Smotts",
	subtitle = "Kapitän ohne Schiff",
	found = "Booty Bay, an den Docks",
	hint = [=[Sucht den Kapitän an den Docks von Booty Bay, der drei Schiffe an die Riesen verloren hat.]=],
	allegiance = "Booty Bay",
	aliases = { "Hecklebury Smotts", "Kapitän Smotts", "Smotts" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Hecklebury Smotts war einst ein stolzer Kapitän, der von {link:booty-bay}Booty Bay{/link} nach {link:ratchet}Ratchet{/link} segelte. Dann kamen die Meeresriesen. Gorlash, Negolash und Mok'rash zertrümmerten sein Schiff, töteten seine Mannschaft und setzten ihn in einem Rettungsboot aus. Er kaufte ein zweites Schiff, nannte es {i}Smotts' Rache{/i} und machte Jagd auf sie, und sie zertrümmerten auch dieses. Sein Koch Sprogger überlebte mit ihm. Die Riesen behielten sogar seine Schätze: Gorlash seine Truhe, Negolash sein Entermesser, Mok'rash seine Schärpe. Smotts will alle drei zurück, und alle drei Riesen tot.]=],
		},
	},
	mentions = {
		{ text = "Die Truhe des Kapitäns" },
		{ text = "Die Schärpe mit Monogramm" },
		{ text = "Das Entermesser des Kapitäns" },
		{ text = "Negolash gegenübertreten" },
	},
})

Translate("deDE", "drizzlik", {
	title = "Drizzlik",
	subtitle = "Lederverarbeiter von Booty Bay",
	found = "Booty Bay",
	hint = [=[Sucht den Goblin in Booty Bay, der sich für den besten Lederverarbeiter der südlichen Meere hält.]=],
	allegiance = "Booty Bay",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Drizzlik ist ein Goblin und Lederverarbeiter, der sich für den besten der südlichen Meere und der alten und neuen Welten hält. Seine Excelsior-Stiefel sind sein ganzer Stolz. Der oberste Erfinder der Tüftlergewerkschaft, Direktor Riddlevox, hat ein Dutzend Paare bestellt, und niemand lässt Riddlevox warten. Drizzlik füttert die Stiefel mit Krokiliskenhaut und macht sie mit Tigerblut geschmeidig. Für die äußere Schicht will er nur die Haut eines alten Salzwasserkrokilisken. Er hat gehört, dass diese Tiere aussterben, und das bereitet ihm Sorgen um sein Handwerk.]=],
		},
	},
	mentions = {
		{ text = "Angebot und Nachfrage" },
		{ text = "Etwas Zusammenbau erforderlich" },
		{ text = "Excelsior" },
	},
})

Translate("deDE", "short-john-mithril", {
	title = "Short John Mithril",
	subtitle = "Meister der Arena",
	found = "Die Arena der Gurubashi",
	hint = [=[Sucht den Piraten, der Schätze in die Arena der Gurubashi bringt.]=],
	allegiance = "Booty Bay",
	aliases = { "Short John" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Short John Mithril ist ein Pirat, der sich die alte Arena der Gurubashi zu seinem eigenen Vergnügen genommen hat. Von Zeit zu Zeit trägt er eine Schatztruhe auf den Sand und überlässt sie dem letzten Kämpfer, der noch steht. Wer eine seiner Marken gewinnt, kommt und fragt, was es noch braucht, um ein Meister der Arena zu sein. Er sagt ihnen, dass eine Marke nicht genügt. Wer genug Blut auf dem Boden der Arena vergießt, den ernennt er zum Großmeister.]=],
		},
	},
	mentions = {
		{ text = "Arenameister" },
		{ text = "Arenagroßmeister" },
	},
})

