	allegiance = "Darkspear · Horde",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Kin'weelay soll der mächtigste Hexendoktor der {link:darkspear-trolls}Darkspear{/link} sein. Er kam nach {link:grom-gol-base-camp}Grom'gol{/link}, um {link:nimboya}Nimboya{/link} zu helfen, doch er hat seine eigenen Gründe, hier zu sein. Er führt den alten Krieg des Stammes gegen die Bloodscalp und die Skullsplitter mit Trophäen und Flüchen. Mit der Hilfe der Geister des Dschungels suchte er das Auge des Geistes und formte es zu einem Seelenstein um. Er spricht mit den Geistern der Toten, und die {link:horde}Horde{/link} bringt ihm Köpfe, deren Geheimnisse sie erfahren will. Er hat ein Bruchstück von Gri'leks Tafel aus dem finsteren Riff für einen Schrein in {link:orgrimmar}Orgrimmar{/link} genommen. Man sagt, er habe auch in der Sprache der Zandali die Geschichte einer versunkenen Trollstadt niedergeschrieben, jener, die sich nun als {link:the-drowned-city}The Drowned City{/link} erhoben hat.]=],
		},
