	allegiance = "Darkspear",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Yenniku ist der jüngste Sohn eines Häuptlings der {link:darkspear-trolls}Darkspear{/link}. Wie es der alte Brauch seines Volkes verlangte, wurde er den Gurubashi von {link:zul-gurub}Zul'Gurub{/link} übergeben. Als sein Stamm mit {link:thrall}Thrall{/link} das {link:stranglethorn-vale}Schlingendorntal{/link} verließ, blieb er zurück und ging verloren. Die Bloodscalp kannten sein Schicksal: Der Hexendoktor {link:zanzil-the-outcast}Zanzil der Ausgestoßene{/link} hatte ihn genommen und mit Leib und Seele an sich gebunden. Nur ein aus dem Auge des Geistes gefertigter Seelenstein konnte ihn aus Zanzils Griff befreien.]=],
		},
		{
			title = "Nicht überliefert",
