	hint = [=[Sucht den Hexendoktor der Bloodscalp an der Seite seines Häuptlings in Zul'Kunda.]=],
	allegiance = "Stamm der Bloodscalp",
	aliases = { "Nezzliok" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Nezzliok der Schreckliche ist der Hexendoktor des Stammes der Bloodscalp. Er wusste, wohin der Darkspearjunge {link:yenniku}Yenniku{/link} gegangen war, und er bewahrte das Geheimnis. Erschlagen, sein Geist in einem Kessel der {link:darkspear-trolls}Darkspear{/link} gebunden, feilschte er noch immer. Er wollte nur sprechen, wenn drei Trophäenschädel aus den Skullsplitterdörfern Balia'mah, Ziata'jai und {link:ruins-of-zul-mamwe}Zul'Mamwe{/link} geholt würden, damit er im Nether Sklaven hätte. Dann sagte er die Wahrheit: {link:zanzil-the-outcast}Zanzil der Ausgestoßene{/link} hielt Yenniku gefangen, und nur große Magie konnte ihn befreien.]=],
		},
	},
