Translate("deDE", "galvan-the-ancient", {
	title = "Galvan der Uralte",
	subtitle = "Schmied des Mithrilordens",
	found = [=[Seine Schmiede zwischen Zul'Gurub und dem Ogerhügel der Mosh'Ogg]=],
	hint = [=[Sucht den alten Schmied, der zwischen Zul'Gurub und dem Ogerhügel lebt.]=],
	allegiance = "Der Mithrilorden",
	aliases = { "Galvan" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Galvan der Uralte ist ein Meisterschmied des Mithrilordens. Er lebt fern jeder Stadt, im östlichen Dschungel zwischen {link:zul-gurub}Zul'Gurub{/link} und dem Hügel der {link:mosh-ogg-ogre-mound}Mosh'Ogg{/link}. Schmiede, die seinen Orden suchen, müssen dessen Anstecknadel durch den Dschungel zu ihm tragen, und die meisten kommen nie an. Der Vertreter des Ordens in {link:booty-bay}Booty Bay{/link} sagt, dass die Gier sie unterwegs aufhält. Wer Galvan erreicht, wird eingeweiht, und er lehrt ihn die Künste des Ordens. Es sei viele Jahre her, sagt er, dass jemand Würdiges gekommen sei.]=],
		},
	},
	mentions = {
		{ text = "Der Mithrilorden" },
		{ text = "Schmelzen, nicht schmelzen" },
		{ text = "Der große Silbertäuscher" },
		{ text = "Die Kunst des Durchtränkens" },
	},
})
